# Creating sets
empty_set = set()  # Cannot use {} as it creates an empty dictionary
fruits = {"apple", "banana", "cherry"}
numbers = {1, 2, 3, 4, 5}

# Adding and removing elements
fruits.add("orange")     # Add a single element
fruits.update(["mango", "grapes"])  # Add multiple elements
fruits.remove("banana")  # Remove element (raises KeyError if not found)
fruits.discard("kiwi")   # Remove if present (no error if not found)

# Set operations
set1 = {1, 2, 3, 4, 5}
set2 = {4, 5, 6, 7, 8}

union = set1 | set2            # Union: {1, 2, 3, 4, 5, 6, 7, 8}
intersection = set1 & set2     # Intersection: {4, 5}
difference = set1 - set2       # Difference: {1, 2, 3}
symmetric_diff = set1 ^ set2  # Symmetric difference: {1, 2, 3, 6, 7, 8}

# Checking if a set is a subset or superset
is_subset = {1, 2}.issubset(set1)     # True
is_superset = set1.issuperset({1, 2})  # True

# Frozen sets - immutable version of sets
frozen = frozenset([1, 2, 3])

# Set comprehension
even_numbers = {x for x in range(10) if x % 2 == 0}  # {0, 2, 4, 6, 8}

